/**
 * Lifecycle state of a remittance.
 * 
 * `Expired` is a *derived* state: it is never persisted. It is computed on
 * read (and reported by `status_of`) for any pre-authorization state whose
 * business `expiry` has passed. Terminal stored states are `Released` and
 * `Refunded`.
 */
export enum Status {
  Created = 0,
  Funded = 1,
  Processing = 2,
  SettlementAuthorized = 3,
  Released = 4,
  Refunded = 5,
  Expired = 6,
}

/**
 * Storage keys.
 * 
 * Instance storage carries contract configuration: roles, the global fee
 * config and per-corridor pause flags. Those must **never** expire silently —
 * a corridor pause that archived itself would silently re-enable a corridor —
 * so they live in instance storage, which is re-extended on every mutating
 * call.
 * 
 * Persistent storage carries the per-remittance records and the two
 * monotonic counters' mirrors used for id allocation.
 */
export type DataKey = {tag: "Admin", values: void} | {tag: "SettlementOracle", values: void} | {tag: "FeeOperator", values: void} | {tag: "FeeConfig", values: void} | {tag: "PausedCorridor", values: readonly [Buffer]} | {tag: "NextId", values: void} | {tag: "Count", values: void} | {tag: "Remittance", values: readonly [u64]};


/**
 * The fee configuration in force for a single remittance.
 * 
 * Snapshotted into [`Remittance::fees`] at creation so release fees are
 * deterministic and auditable regardless of later global configuration
 * changes.
 */
export interface FeeConfig {
  /**
 * Optional anchor/payout-provider fee in basis points. Zero when the
 * corridor has no separate anchor leg.
 */
anchor_bps: u32;
  /**
 * Treasury that receives the anchor fee on release.
 */
anchor_treasury: string;
  /**
 * Corridor/operator fee in basis points.
 */
corridor_bps: u32;
  /**
 * Treasury that receives the corridor fee on release.
 */
corridor_treasury: string;
  /**
 * Platform fee in basis points (1/100 of a percent).
 */
platform_bps: u32;
  /**
 * Treasury that receives the platform fee on release.
 */
platform_treasury: string;
}


/**
 * One remittance commitment.
 */
export interface Remittance {
  /**
 * Time the oracle authorized settlement.
 */
authorized_at: Option<u64>;
  /**
 * Corridor identifier (e.g. `USDC_NGN`). Used by corridor policy and
 * quote integrity.
 */
corridor: Buffer;
  /**
 * Creation time (Unix seconds).
 */
created_at: u64;
  /**
 * Destination payout currency/asset the oracle must attest to (e.g.
 * `NGN`). Off-chain denomination — see `expected_destination_amount`.
 */
destination_asset: Buffer;
  /**
 * Expected destination payout amount the oracle must attest to.
 */
expected_destination_amount: i128;
  /**
 * Business expiry (Unix seconds). Quote integrity and corridor deadlines
 * are enforced against this timestamp; storage TTL is independent.
 */
expiry: u64;
  /**
 * Immutable fee terms this remittance was committed under.
 */
fees: FeeConfig;
  funded_at: Option<u64>;
  /**
 * Monotonic, never-reused identifier.
 */
id: u64;
  /**
 * SHA-256 commitment to the off-chain quote this remittance was priced
 * from. Binds authorization to the exact quote the sender accepted.
 */
quote_hash: Buffer;
  /**
 * The address the escrowed asset is paid to on release. Fixed at
 * creation — recipient substitution is structurally impossible.
 */
recipient: string;
  /**
 * The party whose asset is escrowed. Signs the create; the only party
 * that may fund; the only recipient of a refund.
 */
sender: string;
  /**
 * Time of release or refund (terminal events).
 */
settled_at: Option<u64>;
  /**
 * Gross escrowed amount, in stroops. Fees are carved out of this amount
 * at release; the remainder goes to `recipient`.
 */
source_amount: i128;
  /**
 * SEP-41 / Stellar Asset Contract token address being escrowed.
 */
source_asset: string;
  status: Status;
}


/**
 * What `release` paid out. Returned so the backend can reconcile the escrow
 * payout leg-by-leg without re-deriving the fee math.
 */
export interface ReleaseSummary {
  anchor_fee: i128;
  corridor_fee: i128;
  platform_fee: i128;
  /**
 * Net amount paid to the recipient.
 */
recipient_amount: i128;
}











